function secOffers(r){if(r.sk==='lot:BT-01')return `<ul class="r9-ls">${RS.routes.map(x=>`<li><p><b>${esc(x.name)}</b> <span class="t2">· ${esc(x.form)}</span></p><p class="t2">покупатели: ${x.buyers.map(b=>esc(BY[b].name.replace(/ \(демо\)/,''))+' — '+esc(BY[b].confirmation.label)).join('; ')}</p></li>`).join('')}</ul>${figRoutes()}`;
 if(r.sk==='item:P01')return `<ul class="r9-ls">${PR.sources.map(s=>`<li><p><span class="code">${s.id}</span> <b>${esc(s.what)}</b></p><p class="t2">${s.price_net.cents==null?'<span class="ms u">цена неизвестна</span> · Не прочитано: каталог за регистрацией · '+d5(s.observed_at):s.price_net.display+' без НДС · мин. заказ '+s.moq+' · упаковка '+esc(s.pack)+' · доставка '+esc(s.delivery)+' · '+d5(s.observed_at)}</p></li>`).join('')}</ul>${figOffers()}`;
 return `<ul class="r9-ls"><li><p><b>Поставщик</b> <span class="t2">· 5,40 € за набор · условие «за набор» · доставка «по запросу»</span></p></li><li><p><b>Канал</b> <span class="t2">· amazon.de · FBA — из карточки</span></p></li><li><p><b>Аналоги</b> <span class="t2">· архив рынка (поиск аналогов) · ${fdt(F06.provider_answered_at)}</span></p></li></ul>`}
function secEcon(r){const x=res(r);
 if(r.sk==='lot:BT-01')return `<p class="t2">Три представления — не складываются. Непроданный остаток — не ноль.</p><div class="tbl-wrap" tabindex="0" role="region" aria-label="Экономика маршрутов"><table class="tbl r9-tbl"><thead><tr><th scope="col">Маршрут</th><th scope="col">Прибыль по проданному</th><th scope="col">Деньги на горизонте</th><th scope="col">Экономический итог</th></tr></thead><tbody>${RS.routes.map(y=>`<tr><th scope="row">${esc(y.name)}</th><td><span class="n">${y.result_before_unknown.low.display} – ${y.result_before_unknown.high.display}</span> ${KN.ass}<br><span class="kx">до неизвестных расходов · не посчитано ${unkN(y)}</span></td><td><span class="n">${y.cash_need.peak.display}</span> ${KN.calc}<br><span class="kx">${esc(y.cash_need.locked_for.replace(/\s*\(ГИПОТЕЗА\)/,' · гипотеза'))}</span></td><td><span class="ms u">неизвестно</span><br><span class="kx">остаток ${y.remainder.units?'<span class="n">'+y.remainder.units+' ед.</span>':'0 ед., если покупатель берёт всё'} · ${esc(y.remainder.note)}</span></td></tr>`).join('')}</tbody></table></div>${figCostLot()}${figCash()}`;
 return `<dl class="r9-dl">${x.money.map(m=>`<div><dt>${m[0]}</dt><dd>${m[1]==='неизвестно'?'<span class="ms u">неизвестно</span>':'<b class="n">'+m[1]+'</b>'} ${KN[m[2]]}<span class="kx">${esc(m[3])}</span></dd></div>`).join('')}</dl>${r.sk==='item:P01'?figCostItem():''}`}
function secScen(r){if(r.sk==='lot:BT-01'){const v=B.price.vat;return `<ul class="r9-ls"><li><p><b>НДС · сценарий А</b> <span class="t2">· ${esc(v.scenario_A.label)} · ${v.scenario_A.cash_vat.display} · ${esc(v.scenario_A.condition)}</span></p></li><li><p><b>НДС · сценарий Б</b> <span class="t2">· ${esc(v.scenario_B.label)} · <span class="ms u">неизвестно</span> · ${esc(v.scenario_B.cash_vat.why)}</span></p></li>${RS.routes.map(y=>`<li><p><b>${esc(y.name)}</b> <span class="t2">· ${esc(y.revenue.basis)}</span></p></li>`).join('')}</ul>`}
 if(r.sk==='item:P01'){const t=D.charts.E10_delivery_scenario.teapot;return `<div class="tbl-wrap" tabindex="0" role="region" aria-label="Если посылок X"><table class="tbl" data-density="dense"><caption class="cap-l">Если посылок X · сценарий · X неизвестно</caption><thead><tr><th scope="col" class="num">Посылок</th><th scope="col" class="num">Доставка</th><th scope="col" class="num">Результат после доставки</th></tr></thead><tbody>${t.rows.map(y=>`<tr><td class="num">${y.parcels}</td><td class="num">${y.delivery.display}</td><td class="num">${y.result_after_delivery.display}</td></tr>`).join('')}</tbody></table></div>`}
 return `<p class="t2">Цена продажи — один сценарий: нижняя цена двух сопоставимых наборов. Других сценариев в данных нет.</p>`}
function secRisk(r){const x=res(r);const rk=r.sk==='lot:BT-01'?[...new Set(RS.routes.flatMap(y=>y.risks))]:r.sk==='item:P01'?['5 продавцов на листинге','Объём в прайсе 450 мл против 400 мл на листинге','Совпадение кода ≠ проверка товара']:['Спрос — гипотеза','FBA по аналогу, не по своему набору'];
 return `<div class="r9-2c"><div><h3 class="h3">Риски</h3><ul class="r9-ls">${rk.map(t=>`<li><p>${esc(t)}</p></li>`).join('')}</ul></div><div><h3 class="h3">Что изменит вывод</h3><ul class="r9-ls">${x.change.map(c=>`<li><p>Если ${esc(c[0])} <span class="t2">→ ${esc(c[1])}</span></p></li>`).join('')}</ul></div></div>`}
function secSrc(r){const x=res(r);return `<ul class="r9-ls r9-src">${x.src.map(s=>`<li class="${/^Не прочитано|^не прочитано/.test(s[3])?'r9-na':''}"><p><b>${esc(s[0])}</b> <span class="t2">· ${esc(s[1])}</span></p><p class="r9-ss">${/^Не прочитано|^не прочитано/.test(s[3])?`<span class="ms na">${IC.na}</span>`:''}<span>${esc(s[3])}</span><span class="t2">${s[2]!=='—'?' · '+esc(s[2]):''}</span></p></li>`).join('')}</ul>`}
function histOf(r){const own=ST.hist.filter(h=>h.run===r.id).map(h=>[h.at,h.t]);const base=r.sk==='lot:BT-01'?RS.history.map(h=>[h.at,h.what]):r.sk==='item:P01'?[[PR.asked_at,'Задача: '+PR.question],[PR.answered_at,'Итог RB-D07: '+PR.conclusion]]:[];return base.concat(own)}
function secHist(r){return `<ol class="r9-hl">${histOf(r).map(h=>`<li><span class="tm n">${h[0]===NOW?'01.10 10:00':fdt(h[0])}</span><span>${esc(h[1])}</span></li>`).join('')}</ol>`}

