function resultHtml(r){const x=res(r),sj=SJ(r);
 return `<section class="r9-res" aria-labelledby="r9r-h">
<div class="r9-r0"><p class="eyebrow">Что исследовали</p><p>${esc(x.what)}</p></div>
<div class="r9-r1"><p class="eyebrow" id="r9r-h" tabindex="-1">К чему пришли</p><div class="r9-act"><span class="r9-av">${ACTL[x.action]}</span>${x.partial?'<span class="tag">частично</span>':''}</div>${r.sk==='item:P01'?`<p>${esc(PR.conclusion)}</p>`:''}${x.noStop?`<p class="r9-ns">${NOSTOP}</p>`:''}</div>
<div class="r9-r2"><p class="eyebrow">Почему</p><ol class="r9-why">${x.why.map(w=>`<li><span class="code r9-g">${gc(w[0])}</span><span><b>${GN[w[0]-1]}.</b> ${esc(w[1])}</span></li>`).join('')}</ol></div>
<div class="r9-r3"><div><p class="eyebrow">Чего не хватает</p><ul class="r9-miss">${x.miss.map(t=>`<li><span class="ms u"></span><span>${esc(t)}</span></li>`).join('')}</ul></div><div><p class="eyebrow">Что дальше</p><ul class="r9-nx">${x.next.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="eyebrow r9-ue">Действует до</p><p><b class="n">${x.until}</b> <span class="t2">· ${esc(x.untilWhy)}</span></p></div></div>
${cnt(tally(r,1))}
<div class="r9-docs"><a class="btn btn-s" href="#/research/${r.id}/report">Полный отчёт · 9 листов A4</a><a class="btn btn-s" href="#/research/${r.id}/memo">Меморандум · 2 листа</a></div>
<p class="t2 r9-auth">Вывод исследования — рекомендация. Решение по версии записываете вы ${sj.kind==='lot'?'на странице партии':'в карточке'}; разрешение тратить капитал — вне системы.</p></section>
<div class="u2 r9-more">${[['off',r.sk==='lot:BT-01'?'Предложения и каналы':'Предложения и каналы',r.sk==='lot:BT-01'?'4 маршрута · покупатели — кандидаты':r.sk==='item:P01'?'S1–S4 · 1 источник не прочитан':'поставщик и канал из карточки',secOffers],['eco','Экономика','прибыль по проданному · деньги на горизонте · итог',secEcon],['scn','Сценарии',r.sk==='lot:BT-01'?'НДС А / Б · цены сбыта':r.sk==='item:P01'?'если посылок 1…6':'один сценарий цены',secScen],['rsk','Риски и «Что изменит вывод»',x.change.length+' условия',secRisk],['src','Источники',x.src.length+' · '+x.src.filter(s=>/^Не прочитано|^не прочитано/.test(s[3])).length+' не прочитано',secSrc],['his','История',histOf(r).length+' записей',secHist],['prg','Ход исследования','завершено '+doneN(r)+' '+etap(doneN(r))+' из '+DEMO.stages[r.sk].length,progList]].map(([k,t,s,fn])=>`<section>${LP.acc('r9'+r.id+k,`<span class="sq">${t}</span><span class="tot">${esc(s)}</span>`,fn(r))}</section>`).join('')}</div>`}

/* ══ ход ══ */
const etap=n=>n%10===1&&n%100!==11?'этап':[2,3,4].includes(n%10)&&![12,13,14].includes(n%100)?'этапа':'этапов';
const doneN=r=>DEMO.stages[r.sk].filter((s,i)=>i<r.n&&!s.nd).length;
function stState(r,i){const s=DEMO.stages[r.sk][i];if(i<r.n)return s.fail?'fail':s.nd?'nd':'done';if(i===r.n)return r.st==='input'?'input':r.st==='wait'?'wait':r.st==='run'?'now':'todo';return 'todo'}
const STW={done:'выполнено',fail:'источник недоступен',nd:'не выполнено',input:'требуется уточнение',wait:'ждём внешний ответ',now:'идёт',todo:'впереди'};
function progList(r){return `<ol class="r9-st">${DEMO.stages[r.sk].map((s,i)=>{const k=stState(r,i);return `<li class="r9-si" data-s="${k}"${r._new===i?' data-in="1"':''}><span class="r9-sm" aria-hidden="true">${k==='wait'?IC.clkd:k==='fail'?IC.na:''}</span><div><p class="r9-sn">${esc(s.t)} <span class="r9-sw">· ${STW[k]}</span></p>${k==='fail'?`<p class="r9-sf">${esc(s.fail)}</p>`:k==='nd'?`<p class="t2">${esc(s.nd)}</p>`:s.n&&k!=='todo'?`<p class="t2">${esc(s.n)}</p>`:''}${k==='input'?qForm(r):''}</div></li>`}).join('')}</ol>`}
function qForm(r){const Q=DEMO.q[r.sk];const asked=r.asked||r.at;return `<form class="r9-q" id="r9-q" data-run="${r.id}" aria-labelledby="r9q-h" novalidate><h3 class="h3" id="r9q-h" tabindex="-1">${esc(Q.q)}</h3><p class="t2"><b class="ink">Почему нужен:</b> ${esc(Q.why)}</p><p class="t2">ответить до <b class="n ink">${plus14(asked)}</b> · 14 дней с вопроса ${fdt(asked)}${Q.warn?' · '+esc(Q.warn):''}</p>
<fieldset class="r9-opts" aria-describedby="r9q-e"><legend class="sr-only">Ответ</legend><label class="r9-opt"><input type="radio" name="qa" value="a"><span>${esc(Q.opt)}</span></label><label class="r9-opt"><input type="radio" name="qa" value="own"><span>${esc(Q.own)}</span></label><div class="r9-own" hidden><label class="sr-only" for="r9q-t">Ваш ответ</label><textarea id="r9q-t" name="text" rows="2" placeholder="Ваш ответ"></textarea></div><label class="r9-opt"><input type="radio" name="qa" value="doc"><span>${esc(Q.doc)}</span></label><div class="r9-doc" hidden><label class="t2" for="r9q-f">Документ · в демо файл не загружается и не читается</label><input id="r9q-f" type="file" name="file"></div></fieldset>
<p class="r9-err" id="r9q-e" role="alert" hidden></p><div class="r9-qa"><button class="btn btn-p" type="submit">Ответить</button><span class="t2">ответ записывается как ваш; исследование продолжится</span></div></form>`}
function progHtml(r){const t=tally(r);return `<section class="sec r9-prog" aria-labelledby="r9p-h"><div class="sec-h"><h2 class="h2" id="r9p-h" tabindex="-1">Ход</h2><p class="t2">завершено <span class="n">${doneN(r)}</span> ${etap(doneN(r))} из <span class="n">${DEMO.stages[r.sk].length}</span>${r.st==='wait'?' · ждём внешний ответ: задача у команды LotPrism, срок ответа в данных не задан':''}</p></div>${cnt(t)}${progList(r)}<p class="t2 r9-out">Дальше — вне исследования: решение по версии записываете вы; разрешение на капитал — вне системы.</p></section>`}
function bodyHtml(r){return ['done','part'].includes(r.st)?resultHtml(r):progHtml(r)}

/* ══ страница исследования ══ */
function backOf(r){const sj=SJ(r);const f=r.from&&r.from.split('?')[0]===sj.home?r.from:sj.home;return {href:f,label:sj.back}}
function runPage(id){const r=runOf(id);if(!r)return `<main class="main r9"><h1 class="h1">Исследование не найдено</h1><p class="t2">Возможно, демо Research сброшено.</p><a href="#/research">Исследования</a></main>`;const sj=SJ(r),b=backOf(r);
 return `<main class="main r9" data-screen-label="Исследование ${r.id}"><nav class="r9-bc" aria-label="Возврат"><a href="${b.href}" id="r9-back">${esc(b.label)}</a><a href="#/research" class="t2">Исследования</a></nav>
<header class="r9-h"><p class="eyebrow">${sj.task}${r.code?' · <span class="code">'+r.code+'</span>':''}</p><h1 class="h1">${esc(sj.title)}</h1><p class="r9-meta">${chip(r.st)}${r.direct?'<span class="tag">демо: показано сразу в итоговом состоянии</span>':''}${prevOf(r)?`<span class="t2">версия ${ST.runs.filter(x=>x.sk===r.sk).indexOf(r)+1} · предыдущая: <a href="#/research/${prevOf(r).id}">${prevOf(r).code||prevOf(r).id}</a></span>`:''}<span class="t2">${r.seed?'начато '+fdt(r.at)+(r.fin?' · готово '+fdt(r.fin):''):'запущено 01.10 10:00 · срез демо'} · демонстрация: этапы и ответы — из сохранённых данных, модели не вызываются</span></p></header>
<div id="r9-body">${bodyHtml(r)}</div></main>`}

